"""Isolated UI-test data; every assistant reply is generated by real own weights."""
import hashlib
import os
from pathlib import Path
import shutil
import sys
import time

ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT))
from lambda_cli.chats import ChatStore
from lambda_cli.engine import Engine,Settings
from lambda_cli.models import ModelManager,atomic_json
from lambda_cli.quota import Quota
from lambda_cli.session import Session

directory=Path(sys.argv[1]).resolve()
assert directory.name.startswith('lambda-desktop-test-'),'Refusing to seed a real user data directory.'
os.environ['LAMBDA_DATA_HOME']=str(directory)
directory.mkdir(parents=True,exist_ok=True);(directory/'models').mkdir(exist_ok=True)
manager=ModelManager(directory);state=manager.state()
for identifier in ['lambda-2.4','lambda-code-3']:
    source=ROOT/'models'/f'{identifier}.npz';filename=f'{identifier}-r1.npz'
    shutil.copyfile(source,directory/'models'/filename)
    state['installed'][identifier]=dict(filename=filename,revision=1,sha256=hashlib.sha256(source.read_bytes()).hexdigest())
state['active']='lambda-code-3';atomic_json(directory/'models.json',state)
quota=Quota();store=ChatStore();identifiers=[]
for model,question,title in [('lambda-2.4','My name is Alex.','Getting to know Lambda'),
        ('lambda-2.4','What is gravity?','A little curiosity'),
        ('lambda-code-3','make a code in python printing hello','Python starter')]:
    session=Session(Engine(manager.resolve(model)),Settings(seed=33103,max_tokens=192),quota=quota,manager=manager,store=store)
    session.add_user(question);session.complete(session.generate(question))
    session.chat_title=title;session.persist();identifiers.append(session.chat_id)
store.set_active(identifiers[-1])
# A fixture-only usage level makes progress and reset fields easy to verify.
with quota.connect() as db:db.execute('UPDATE allowance SET used=?, started=? WHERE id=1',(250000,time.time()-7200))
atomic_json(directory/'desktop.json',dict(theme='light',accent='orange',density='comfortable',fontSize=16,displayName='Alex',responseTokens=192))
print('Seeded three isolated conversations using actual model-generated replies.')

# Optional actual published image weights; synthetic reference fixtures are ONLY
# isolated test inputs, never screenshots presented as successful real photographs.
if os.environ.get('LAMBDA_ORION_MODEL'):
    import json
    from urllib.parse import urlencode
    from PIL import Image,ImageDraw
    from lambda_cli.image_models import ImageModels
    from lambda_cli.image_generation import References
    image_models=ImageModels(directory);entry=image_models.entries()[0]
    source=Path(os.environ['LAMBDA_ORION_MODEL']);assert hashlib.sha256(source.read_bytes()).hexdigest()==entry['sha256']
    folder=directory/'image-models';folder.mkdir(exist_ok=True);filename='orion-image-1-r1.npz';shutil.copyfile(source,folder/filename)
    installed={'orion-image-1':dict(filename=filename,revision=1,sha256=entry['sha256'])}
    if os.environ.get('LAMBDA_ORION_12_MODEL'):
        entry=next(m for m in image_models.entries() if m['id']=='orion-1.2')
        source=Path(os.environ['LAMBDA_ORION_12_MODEL']);assert hashlib.sha256(source.read_bytes()).hexdigest()==entry['sha256']
        filename='orion-1.2-r1.npz';shutil.copyfile(source,folder/filename)
        installed['orion-1.2']=dict(filename=filename,revision=1,sha256=entry['sha256'])
    atomic_json(directory/'image-models.json',dict(installed=installed,active='orion-image-1'))
    cache=directory/'image-playground/references';cache.mkdir(parents=True,exist_ok=True)
    for query in ['test subject face human','missing reference']:
        key=hashlib.sha256(('safe-images-v1:'+query).encode()).hexdigest()
        atomic_json(cache/(key+'.json'),dict(safeSearch='strict',results=[]))
    for query,ident,color in [('test subject','FIXTURE_SUBJECT',(190,100,50)),('test background','FIXTURE_BACKGROUND',(20,40,80)),('person in suit','FIXTURE_SCENE',(70,110,170))]:
        photo='https://tse1.mm.bing.net/th/id/'+ident+'.jpg'
        key=hashlib.sha256(('safe-images-v1:'+query).encode()).hexdigest()
        atomic_json(cache/(key+'.json'),dict(safeSearch='strict',results=[dict(title='Synthetic '+query,thumbnail=photo,url='https://example.org/fixtures/'+ident)]))
        image=Image.new('RGB',(256,256),color)
        if query=='test subject':ImageDraw.Draw(image).ellipse((70,40,190,220),fill=(230,210,160))
        identifier='safe:'+hashlib.sha256(photo.encode()).hexdigest()
        image.save(cache/(hashlib.sha256(identifier.encode()).hexdigest()+'.png'))
